//! 🧪️ Original transition pages match canonical wire and third-party BLAKE3 through every funded handoff and cancellation.
use super::*;
use semio_framework_os_spr::{InputReplacement,HistoryTransition,TransitionSupersede,SupersededInput};
fn turn()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:262144,maximum_depth:4096}}
fn exact(p:RetainedCloneProgress,heap:semio_framework_trace::HeapAllocationObservation){assert!(p.fits(turn()));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
fn denied(mut g:RetainedCloneGrant,d:RetirementDemand,axis:usize)->Option<RetainedCloneGrant>{let value=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if value==0{return None}match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes=value-1,2=>g.maximum_capacity_bytes=value-1,3=>g.maximum_release_bytes=value-1,_=>g.maximum_depth=value-1}Some(g)}
fn reference_id(timestamp:HybridLogicalTimestamp,payload:&[u8])->String{fn number(out:&mut Vec<u8>,mut value:u64){loop{out.push((value as u8&127)|if value>=128{128}else{0});value>>=7;if value==0{break}}}let mut input=Vec::new();for value in [timestamp.actor,timestamp.physical_ms,timestamp.logical,payload.len()as u64]{number(&mut input,value);}input.extend_from_slice(payload);format!("transition-{}",blake3::hash(&input).to_hex()[..16].to_owned())}
fn close_value<T:semio_framework_value::retirement::RetireOwned>(value:T){let mut value=Some(value);let mut close=RetainedCloneClose::default();for _ in 0..10000{if value.is_none()&&close.is_empty(){return}let d=close.next_owner_demands::<T>(value.is_some(),&None,4096).unwrap();let g=RetainedCloneGrant{maximum_copy_bytes:turn().maximum_copy_bytes.max(d.copy_bytes),maximum_capacity_bytes:turn().maximum_capacity_bytes.max(d.capacity_bytes),..turn()};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||if let Some(step)=close.begin_granted(&mut value,g).unwrap(){step}else{close.step_granted(g).unwrap()});assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("original transition output did not close")}
struct FixturePins<'a>(&'a[semio_framework_os_spr::TransitionPin]);
impl semio_framework_os_spr::HistoryTransitionPinSource for FixturePins<'_>{fn source_identity(&self)->(usize,usize){(self.0.as_ptr()as usize,self.0.len())}fn len(&self)->usize{self.0.len()}fn uri_part(&self,row:usize,part:usize)->Option<&str>{self.0.get(row).and_then(|pin|match part{0=>Some(pin.child_uri.as_str()),1..=6=>Some(""),_=>None})}fn checkpoint_id(&self,row:usize)->Option<&str>{self.0.get(row).map(|pin|pin.checkpoint_id.as_str())}}
fn borrowed(owner:&mut OriginalHistoryTransitionPayload,source:&HistoryTransition,epoch:u64,time:HybridLogicalTimestamp,grant:RetainedCloneGrant,foreign:Option<&str>)->Result<RetainedCloneProgress,ValueError>{match source{HistoryTransition::Repin{checkpoint_id,pinned_checkpoint_id,pins}=>owner.advance_repin_view(&HistoryTransitionRepinView{checkpoint_id:foreign.unwrap_or(checkpoint_id),pinned_checkpoint_id,pins:&FixturePins(pins)},epoch,time,grant),HistoryTransition::Revert{mutation_ids}|HistoryTransition::Reinstate{mutation_ids}=>owner.advance_edits_view(&HistoryTransitionEditsView{mode:match (matches!(source,HistoryTransition::Revert{..}),foreign.is_some()){(true,false)|(false,true)=>HistoryTransitionEditMode::Revert,_=>HistoryTransitionEditMode::Reinstate},mutation_ids},epoch,time,grant),HistoryTransition::Commit(c)=>owner.advance_commit_view(&HistoryTransitionCommitView{checkpoint_id:foreign.unwrap_or(&c.checkpoint_id),parent_id:c.parent_id.as_deref(),change_id:&c.change_id,mutation_ids:&c.mutation_ids,description:c.description.as_deref(),saved_at:&c.saved_at,authors:&c.authors,message:c.message.as_deref(),timestamp:&c.timestamp,line_id:c.line_id.as_deref()},epoch,time,grant),HistoryTransition::Branch{alternative_id,name,checkpoint_id}=>owner.advance_branch_view(&HistoryTransitionBranchView{alternative_id,name,checkpoint_id:foreign.unwrap_or(checkpoint_id)},epoch,time,grant),_=>panic!("borrowed native fixture must name canonical graph facts")}}
#[test]
fn original_borrowed_transition_payload_preserves_full_field_identity_epoch_hash_and_partial_close(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../🔨️modules/📡️replication/🔗️causal/🧪️tests/🧫️fixtures/🧫️history-transition/🔣️.json")).unwrap();let mut checked=0;for case in law["cases"].as_array().unwrap(){if case["expect"]["outcome"]!="accepted"{continue}let hex=case["payloadHex"].as_str().unwrap();let bytes:Vec<_>=(0..hex.len()).step_by(2).map(|at|u8::from_str_radix(&hex[at..at+2],16).unwrap()).collect();let source=semio_framework_os_spr::decode_history_transition(&bytes).unwrap();let foreign=match &source{HistoryTransition::Repin{checkpoint_id,..}=>checkpoint_id.clone(),HistoryTransition::Revert{..}|HistoryTransition::Reinstate{..}=>String::from("foreign-mode"),HistoryTransition::Commit(c)=>c.checkpoint_id.clone(),HistoryTransition::Branch{checkpoint_id,..}=>checkpoint_id.clone(),_=>continue};checked+=1;for cut in [0,1,8,32,128,usize::MAX]{let mut owner=OriginalHistoryTransitionPayload::new(262144,1048576).unwrap();let time=HybridLogicalTimestamp::new(71,19);for index in 0..100000{if index==cut||owner.ready(){break}let d=owner.demands(4096).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);for axis in 0..5{if let Some(g)=denied(turn(),d,axis){let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||borrowed(&mut owner,&source,71,time,g,None).unwrap());exact(p,heap);assert_eq!(p,Default::default());}}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||borrowed(&mut owner,&source,71,time,turn(),None).unwrap());exact(p,heap);for (epoch,field) in [(72,None),(71,Some(foreign.as_str()))]{let before=(owner.phase,owner.measured,owner.length,owner.offset,owner.output.len());let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||borrowed(&mut owner,&source,epoch,time,turn(),field).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((owner.phase,owner.measured,owner.length,owner.offset,owner.output.len()),before);}assert!(index<99999)}if cut==usize::MAX{assert!(owner.ready());let((payload,id,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take(turn()).unwrap().unwrap());exact(p,heap);assert_eq!(payload.iter().collect::<Vec<_>>(),bytes);assert_eq!(id.0,reference_id(time,&bytes));close_value((payload,id));}for index in 0..100000{if owner.terminal_is_empty(){break}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(turn()).unwrap());exact(step.progress(),heap);assert!(index<99999)}assert!(owner.terminal_is_empty());}close_value(source);}assert!(checked>=7);}
#[test]fn original_supersession_payload_preserves_pages_identity_denials_and_partial_close(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../🔨️modules/📡️replication/🔗️causal/🔀️transition/📤️wire/🧪️tests/🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){for cut in [0,1,16,128,256,usize::MAX]{let drafts=case["inputs"].as_array().unwrap().iter().map(|input|{let replacement=if input["withdrawn"].as_bool().unwrap_or(false){InputReplacement::Withdrawn}else{InputReplacement::Input{schema:input["schema"].as_str().unwrap().into(),payload:(0..input["payloadLength"].as_u64().unwrap()as usize).map(|index|(input["payloadSeed"].as_u64().unwrap()as usize+index*31)as u8).collect()}};(MutationId(input["target"].as_str().unwrap().into()),replacement)}).collect::<HistoryInputDrafts>();let scope=case["scope"].as_str();let timestamp=HybridLogicalTimestamp{actor:7,physical_ms:19,logical:2};let mut owner=OriginalHistoryTransitionPayload::new(262144,1048576).unwrap();let mut completed=false;for index in 0..100000{if index==cut{break}if owner.source.is_some(){let before=(owner.phase,owner.measured,owner.length,owner.offset,owner.output.len());let(error,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance_supersession(&drafts,scope,HybridLogicalTimestamp{logical:timestamp.logical+1,..timestamp},turn()).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((owner.phase,owner.measured,owner.length,owner.offset,owner.output.len()),before);}let d=owner.demands(4096).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);for axis in 0..5{if let Some(g)=denied(turn(),d,axis){let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance_supersession(&drafts,scope,timestamp,g).unwrap());exact(p,heap);assert_eq!(p,Default::default());}}let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance_supersession(&drafts,scope,timestamp,turn()).unwrap());exact(p,heap);if owner.ready(){completed=true;break}assert!(index<99999);}if cut==usize::MAX{assert!(completed);let transition=HistoryTransition::Supersede(TransitionSupersede{scope:scope.map(str::to_owned),inputs:drafts.iter().map(|(target,replacement)|SupersededInput{target:target.clone(),replacement:replacement.clone()}).collect()});let expected=semio_framework_os_spr::encode_history_transition(&transition);let((payload,id,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take(turn()).unwrap().unwrap());exact(p,heap);assert_eq!(payload.len(),case["wireBytes"].as_u64().unwrap()as usize);assert_eq!(payload.retained_bytes().iter().copied().collect::<Vec<_>>(),expected);assert_eq!(id.0,reference_id(timestamp,&expected));close_value((payload,id));}owner.begin_close();for index in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);let g=RetainedCloneGrant{maximum_copy_bytes:turn().maximum_copy_bytes.max(d.copy_bytes),maximum_capacity_bytes:turn().maximum_capacity_bytes.max(d.capacity_bytes),..turn()};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(index<99999);}assert!(owner.terminal_is_empty());close_value(drafts);}}}
